templates.template:
.p-footer
{
	.xf-publicFooter();

	a
	{
		.xf-publicFooterLink();
	}
}

.p-footer-inner
{
	.m-pageWidth();
	.m-pageInset();

	padding-top: @xf-paddingMedium;
	padding-bottom: @xf-paddingLarge;
}

.p-footer-row
{
	.m-clearFix();

	margin-bottom: (@xf-paddingLarge * -1);
	<xf:if is="property('xgt_Sv13_infoBox_etkin')">
		border-top: 1px solid @xf-borderColor;
		padding-top: 20px;
	</xf:if>

}

.p-footer-row-main
{
	float: left;
	margin-bottom: @xf-paddingLarge;
}

.p-footer-row-opposite
{
	float: right;
	margin-bottom: @xf-paddingLarge;
}

.p-footer-linkList
{
	.m-listPlain();
	.m-clearFix();

	> li
	{
		float: left;
		margin-right: .5em;

		&:last-child
		{
			margin-right: 0;
		}

		a
		{
			padding: 2px 4px;
			border-radius: @xf-borderRadiusSmall;

			&:hover
			{
				text-decoration: none;
				background-color: fade(@xf-publicFooterLink--color, 10%);
			}
		}
	}
}

.p-footer-rssLink
{
	> span
	{
		position: relative;
		top: -1px;

		display: inline-block;
		width: 1.44em;
		height: 1.44em;
		line-height: 1.44em;
		text-align: center;
		font-size: .8em;
		background-color: #FFA500;
		border-radius: 2px;
	}

	.fa-rss
	{
		color: white;
	}
}

.p-footer-copyright
{
	margin-top: @xf-elementSpacer;
	text-align: center;
	font-size: @xf-fontSizeSmallest;
}

.p-footer-debug
{
	margin-top: @xf-paddingLarge;
	text-align: right;
	font-size: @xf-fontSizeSmallest;

	.pairs > dt { color: inherit; }
}

@media (max-width: @xf-responsiveMedium)
{
	.p-footer-row-main,
	.p-footer-row-opposite
	{
		float: none;
	}

	.p-footer-copyright
	{
		text-align: left;
		padding: 5px 5px; // aligns with other links
	}
}

@media (max-width: @xf-responsiveMedium)
{
	.p-footer-copyright 
	{
		font-size:13px;
		width: 100%;
		text-align: center;
	}
	.p-footer .p-footer-copyright .u-concealed
	{
		margin-bottom:10px;
		display: inline-block;
	}
}

// navEl / Navigation Elements for header navigation

<xf:comment>
	//--- XGTSV13 - Aleternatif header ve navbar
</xf:comment>
._xgtSv13__alternaHeader
{
	.p-header 
	{
		color: var(--xgtSv13-renk-grup-metin);
		background:var(--xgtSv13-renk-grup-birincil);

		a { color: var(--xgtSv13-renk-grup-metin); }

		.xgtSv13-metin__logo a
		{
			color: var(--xgtSv13-renk-grup-metin);
			&:hover {
				color: var(--xgtSv13-renk-grup-ikincil);
			}
		}
	}

	.p-sectionLinks 
	{
		background: var(--xgtSv13-renk-grup-birincil-vr);
		color: var(--xgtSv13-renk-grup-metin);

		.altnav__butonlar {
			background:var(--xgtSv13-renk-grup-birincil);
		}

	}

	.p-nav-list .p-navEl.is-selected {
		color:var(--xgtSv13-renk-grup-metin);
		background: var(--xgtSv13-renk-grup-birincil-vr);
	}
	.p-navgroup {
		color:var(--xgtSv13-renk-grup-metin);
		background: var(--xgtSv13-renk-grup-birincil-vr);
		border: solid 1px var(--xgtSv13-renk-grup-birincil);
	}
	.p-navgroup-link 
	{
		border-left: solid 1px var(--xgtSv13-renk-grup-birincil);

		&:hover {
			background: var(--xgtSv13-renk-grup-ikincil);
			color:var(--xgtSv13-renk-grup-metin);
		}
	}	
	.p-nav-scroller .hScroller-action
	{
		color:var(--xgtSv13-renk-grup-metin);

		&.hScroller-action--start {
			background: linear-gradient(90deg, var(--xgtSv13-renk-grup-birincil-vr) 0%, var(--xgtSv13-renk-grup-birincil) 100%);
		}
		&.hScroller-action--end {
			background: linear-gradient(90deg,var(--xgtSv13-renk-grup-birincil) 0%, var(--xgtSv13-renk-grup-birincil-vr) 100%);

		}
	}
}
<xf:comment>
	//--- XGTSV13 - Normal header ve navbar
</xf:comment>
.p-header {
	color: @xf-textColor;
	background: @xf-pageBg;
}

.p-sectionLinks 
{
	background: var(--xgtSv13-renk-grup-birincil);
	color: var(--xgtSv13-renk-grup-metin);
	padding: 5px;

	.altnav__butonlar {
		background: var(--xgtSv13-renk-grup-birincil-vr);
		color: var(--xgtSv13-renk-grup-metin);
		border-radius: var(--xgt-global-radius-m);
	}

}


.p-nav-list .p-navEl.is-selected {
	color: @xf-textColor;
	background: @xf-contentAltBg;
}
//--- ####

.p-navEl
{
	.m-clearFix();
}

.p-navEl-linkHolder
{
	float: left;
}

.p-navEl-link
{
	float: left;
	.m-transition(opacity, background; @_nav-elTransitionSpeed);

	&.p-navEl-link--menuTrigger
	{
		cursor: pointer;

		&:after
		{
			.m-menuGadget(); // .58em
			opacity: .5;
			.m-transition(opacity; @_nav-elTransitionSpeed);
		}

		&:hover:after
		{
			opacity: 1;
		}
	}
}

.p-navEl-splitTrigger
{
	float: left;
	opacity: .5;
	cursor: pointer;
	text-decoration: none;
	.m-transition(all; @_nav-elTransitionSpeed);

	&:after
	{
		.m-menuGadget(); // .58em
		line-height: 1;
	}

	&:hover
	{
		opacity: 1;
		text-decoration: none;
	}
}

// HEADER NAV ROW

.p-nav
{
	//.xf-publicNav();

	@media (max-width: @xf-responsiveMedium)
	{
		background: var(--xgtSv13-renk-grup-birincil);
		color: var(--xgtSv13-renk-grup-metin);
		padding: 10px 0px;
	}
	a
	{
		color: inherit;
	}

	.p-navSticky.is-sticky &
	{
		.p-nav-list .p-navEl.is-selected,
		.p-account
		{
			border-radius: 0;
		}
	}
}

.p-nav-inner
{
	.m-pageWidth();
	.m-pageInset(0px);
	.m-clearFix();
	display: flex;
	align-items: flex-end;
}



.p-nav .p-nav-menuTrigger
{
	display: none;
	vertical-align: middle;
	align-self: center;
	margin-left: max(0px, (@xf-pageEdgeSpacer - 6px));
	margin-right: 5px;
	padding: @xf-publicNavPaddingV 8px;
	color: inherit;

	&:hover
	{
		text-decoration: none;
	}

	i:after
	{
		.m-faBase();
		font-size: @xf-fontSizeLargest;
		.m-faContent(@fa-var-bars); //, .88em
		vertical-align: bottom;
	}

	.p-nav-menuText
	{
		display: none;
	}
}

.p-nav-smallLogo
{
	display: none;
	max-width: 100px;
	align-self: center;

	img
	{
		display: block;
		max-height: @header-navHeight;

		&:not([src$=".svg"])
		{
			width: auto;
		}
	}
}

.p-nav-scroller
{
	margin-right: auto;
	max-width: 100%;

	.hScroller-scroll:not(.is-calculated)
	{
		// IE11 seems to want to flash a vertical scrollbar without this here
		overflow: hidden;
	}

	.hScroller-action
	{
		.m-hScrollerActionColorVariation(
			xf-default(@xf-publicNav--background-color, transparent),
			xf-default(@xf-publicNav--color, ~""),
			xf-intensify(@xf-publicNav--color, 10%)
		);
	}
}

.p-nav-list
{
	.m-listPlain();
	.m-clearFix();

	font-size: 0;

	// this applies padding that will be contained within the scroller.
	// it needs font-size 0 to not create extra space though
	&:before,
	&:after
	{
		display: inline-block;
		width: @xf-pageEdgeSpacer;
		content: '';
	}

	> li
	{
		display: inline-block;
		vertical-align: bottom;
		font-size: @xf-fontSizeNormal;

		&:first-child
		{
			margin-left: 0;
		}
	}

	.m-navElHPadding(@xf-publicNavPaddingH);

	.p-navEl
	{
		.xf-publicNavTab();
		.m-transition(all; @_nav-elTransitionSpeed);

		&.is-selected
		{
			.xf-publicNavSelected();

			.p-navEl-link
			{
				padding-right: @xf-publicNavPaddingH; // since the split trigger is hidden

				&:hover
				{
					background: none;
					text-decoration: none;
				}
			}

			.p-navEl-splitTrigger
			{
				display: none;
			}
		}

		&:not(.is-selected):not(.is-menuOpen)
		{
			&:hover,
			.p-navEl-link:hover,
			.p-navEl-splitTrigger:hover
			{
				.xf-publicNavTabHover();
			}
		}

		&.is-menuOpen
		{
			.xf-publicNavTabMenuOpen();

			border-top-left-radius: xf-default(@xf-publicNavSelected--border-top-left-radius, 0);
			border-top-right-radius: xf-default(@xf-publicNavSelected--border-top-right-radius, 0);

			.m-dropShadow(0, 5px, 10px, 0, .35);

			a
			{
				text-decoration: none;
				opacity: 1;
			}
		}
	}

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		padding-top: @xf-publicNavPaddingV;
		padding-bottom: @xf-publicNavPaddingV;
	}
}

.p-navSticky--primary.is-sticky
{
	.p-nav-list
	{
		.p-navEl-link.p-navEl-link--splitMenu
		{
			padding-right: (@xf-publicNavPaddingH / 4);
		}

		.p-navEl.is-selected .p-navEl-splitTrigger
		{
			display: inline;
			position: relative;

			&:before
			{
				content: '';
				position: absolute;
				left: 0;
				top: 5px;
				bottom: 5px;
				width: 0;
				border-left: @xf-borderSize solid fade(xf-default(@xf-publicNavSelected--color, transparent), 35%);
			}
		}
	}
}

@media (max-width: @xf-publicNavCollapseWidth)
{
	.has-js
	{
		.p-nav-inner
		{
			//min-height: 45px;
		}

		.p-nav .p-nav-menuTrigger
		{
			display: inline-block;
		}

		.p-nav-smallLogo
		{
			display: inline-block;
		}

		.p-nav-scroller
		{
			display: none;
		}
	}
}

// ACCOUNT/VISITOR/SEARCH SECTION

.p-nav-opposite
{
	margin-left: auto;
	margin-right: @xf-pageEdgeSpacer;
	text-align: right;
	flex-shrink: 0;
}

.p-navgroup
{
	float: left;
	.m-clearFix();
	background: @xf-publicHeaderAdjustColor;
	border-radius: var(--xgt-global-radius-m);
	border: solid 1px @xf-borderColor;
	overflow: hidden;

	//-- [Graves] Sv13 Düzenlemesi - border kaldır
	@media (max-width: @xf-responsiveMedium)
	{
		border:none;
	}

	&.p-discovery
	{
		margin-left: .5em;

		&.p-discovery--noSearch
		{
			margin-left: 0;
		}
	}
}

.p-navgroup-link
{
	float: left;
	padding: @xf-publicNavPaddingV @_navAccount-hPadding;
	border-left: 1px solid @xf-borderColor;

	&:first-of-type
	{
		border-top-left-radius: 0 0 var(--xgt-global-radius-m) var(--xgt-global-radius-m);
		border-left: none;
	}

	&:last-of-type
	{
		border-top-right-radius: var(--xgt-global-radius-m) var(--xgt-global-radius-m) 0 0 ; 
	}

	&:hover
	{
		text-decoration: none;
		background: xf-intensify(@xf-publicHeaderAdjustColor, 5%);

		@media (max-width: @xf-responsiveMedium)
		{
			background: fade(@xf-publicHeaderAdjustColor, 5%);
		}
	}

	&.p-navgroup-link--user
	{
		.m-overflowEllipsis();
		max-width: 150px;

		.avatar
		{
			.m-avatarSize((@xf-fontSizeNormal * @xf-lineHeightDefault));
		}
	}

	&.badgeContainer
	{
		position: relative;

		&:after
		{
			position: absolute;
			left: (@_navAccount-hPadding - 6px);
			top: (@xf-publicNavPaddingV - 2px);
			padding: 1px 3px;
			margin: 0;
			font-size: 10px;
			line-height: 11px;
		}

		&:hover,
		&.badgeContainer--highlighted
		{
			opacity: 1;
		}
	}

	&.is-menuOpen
	{
		.xf-publicNavTabMenuOpen();
		.m-dropShadow(0, 5px, 10px, 0, .35);
		opacity: 1;
	}

	&.p-navgroup-link--iconic
	{
		i:after
		{
			.m-faBase();
			display: inline-block;
			min-width: 1.2em;
			text-align: center;
		}
	}

	&.p-navgroup-link--conversations i:after
	{
		.m-faContent(@fa-var-envelope, 1em);
		mask-size: 1.2em 1em;
		-webkit-mask-size: 1.2em 1em;
	}

	&.p-navgroup-link--alerts i:after
	{
		.m-faContent(@fa-var-bell); //, .88em
	}

	&.p-navgroup-link--bookmarks i:after
	{
		.m-faContent(@fa-var-bookmark); //, .75em
	}

	&.p-navgroup-link--whatsnew i:after
	{
		.m-faContent(@fa-var-bolt); //, .63em
	}

	&.p-navgroup-link--search i:after
	{
		.m-faContent(@fa-var-search); //, 1em
	}
}

.p-navgroup-link--whatsnew
{
	display: none;

	.p-navgroup-link:first-of-type& + .p-navgroup-link
	{
		border-top-left-radius: @xf-borderRadiusMedium;
		border-left: none;
	}
}

@media (max-width: @xf-responsiveWide)
{
	.p-navgroup-link
	{
		&.p-navgroup-link--iconic .p-navgroup-linkText,
		&.p-navgroup-link--textual i
		{
			display: none;
		}

		&.p-navgroup-link--textual
		{
			.m-overflowEllipsis();
			max-width: 110px;
		}

		&.p-navgroup-link--iconic i:after
		{
			text-align: center;
		}
	}
}

@media (max-width: @xf-publicNavCollapseWidth)
{
	.p-navgroup-link--whatsnew
	{
		display: block;
	}

	.has-js
	{
		.p-nav-opposite
		{
			align-self: center;
			margin-right: max(0px, (@xf-pageEdgeSpacer - 6px));

			.p-navgroup
			{
				background: none;
				margin-left: 0;
			}

			.p-navgroup-link
			{
				border: none;
				border-radius: @xf-borderRadiusMedium;

				&.is-menuOpen
				{
					.m-borderBottomRadius(0);
				}

				&.badgeContainer
				{
					opacity: 1;
				}
			}
		}
	}
}

@media (max-width: 359px)
{
	.p-navgroup-link&.p-navgroup-link--user
	{
		display: none;
	}
}

@media (max-width: 500px)
{
	.p-navgroup-link.p-navgroup-link--register
	{
		display: none;
	}
}

// ######################################### STAFF BAR #################################

<xf:comment>
	//--- [Graves] SV13 - Admin bar alanı & hızlı bağlantılar...
</xf:comment>
.xgtSv13_adminBar
{
	background: @xf-contentAltBg;
	padding: 10px 0;

	&._adminBar__bar__sinir { border-bottom: solid 1px @xf-borderColor;}

	._adminBar__bar
	{
		justify-content: space-between;
		align-items: center;

		@media (max-width: (@xf-responsiveMedium + 1px)){
			&.xgt__displayFlex{display:block;} //--Admin bar mobil kontrol.
		}

		._adminBar {
			&__controller {
				flex: 1 0 0;
				padding: 5px 0px;
			}

			&__hizlibaglanti {
				flex: 0 0 auto;
				position: relative;

				._hizlibaglanti__buton
				{
					padding: 4px 6px;

					&:hover {
						text-decoration: none;
						background: @xf-pageBg;
						border-radius: 4px;
					}
				}
			}
		}
	}
}	
._hizlibaglanti__menu
{
	&.menu--superWideee
	{
		width: 33%;
		max-width: calc(~'100% - @{xf-pageEdgeSpacer}');

		.listColumns.listColumns--3 {column-gap: 0em;}
	}
	.menu-linkRow i.fa--xf {
		width: 14px;
	}
}
.p-staffBar-link
{
	&:before {	
		display: inline-block;
		padding-right: 5px;	
	}
}
a[href*="admin.php"].p-staffBar-link::before {	
	.m-faContent(@fa-var-user-shield);
}

.p-staffBar-link {
	&.menuTrigger:before {.m-faContent(@fa-var-user-cog);}
	&.badgeContainer--highlighted:before {.m-faContent(@fa-var-bug);}
}
<xf:comment>
	//--- [Graves] SV13 - Admin bar alanı & hızlı bağlantılar...
</xf:comment>


.p-staffBar
{
	.xf-publicStaffBar();

	@media (max-width: (@xf-responsiveMedium + 1px)){
		border-left: 0px;
	}

	a { color: inherit;	}

	.hScroller-action
	{
		.m-hScrollerActionColorVariation(
			xf-default(@xf-publicStaffBar--background-color, transparent),
			xf-default(@xf-publicStaffBar--color, ~""),
			xf-intensify(@xf-publicStaffBar--color, 10%)
		);
	}
}

.p-staffBar-inner
{
	.m-pageWidth();
	.m-pageInset();
	.m-clearFix();

	padding-top: 4px;
	padding-bottom: 4px;
}

.p-staffBar-link
{
	display: inline-block;
	vertical-align: top;
	color: inherit;
	padding: 4px @xf-paddingMedium;
	margin-right: .35em;

	&:last-child
	{
		margin-right: 0;
	}

	&:hover
	{
		text-decoration: none;
		background: @xf-pageBg;
		border-radius: @xf-borderRadiusSmall;
	}
}

.p-title
{
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	max-width: 100%;
	margin-bottom: -5px;

	&.p-title--noH1
	{
		flex-direction: row-reverse;
	}
}

h1, h2, h3, h4, h5, h6 {
	font: inherit;
}
.p-title-value
{
	padding: 0;
	margin: 0 auto 5px 0;
	min-width: 0;
	font-weight: 500;
	font-size: clamp(1.3em, 2vw, 1.8em);
}

.p-title-pageAction
{
	margin-bottom: 5px;
}

.p-description
{
	margin: 5px 0 0;
	padding: 0;
	font-size: @xf-fontSizeSmall;
	color: @xf-textColorMuted;
}

:root
{
	--f-carousel-theme-color: @xf-linkColor;
}

.carousel
{
	.m-clearFix();
	margin-bottom: calc(var(--f-carousel-dots-height) + @xf-elementSpacer);

	&.carousel--withFooter
	{
		margin-bottom: @xf-elementSpacer;
	}
}

.carousel-body
{
	&,
	&.f-carousel
	{
		--xf-slidesPerPage: 1;
		--f-carousel-spacing: @xf-paddingMedium;
	}

	display: flex;
	overflow: hidden;
	.m-listPlain();

	.carousel-container
	{
		flex: 0 0 auto;
		width: calc((100% - (var(--f-carousel-spacing) * (var(--xf-slidesPerPage) - 1))) / var(--xf-slidesPerPage));
		margin: 0 var(--f-carousel-spacing) 0 0;

		& when(@rtl)
        {
            margin: 0 0 0 var(--f-carousel-spacing);
        }
	}

	@media (min-width: 700px)
	{
		&.carousel-body--show2
		{
			--xf-slidesPerPage: 2;
		}
	}
}

.carousel-item
{
	width: 100%;
	height: 100%;
	.xf-contentBase();
	.xf-blockBorder();
	border-radius: var(--xgt-global-radius--m);
	padding: @xf-blockPaddingV @xf-blockPaddingH;
}

.carousel-footer
{
	position: relative;
	font-size: @xf-fontSizeSmall;
	z-index: @zIndex-1;

	margin-top: var(--f-carousel-dots-height);
	text-align: center;

	@media (min-width: @xf-responsiveNarrow)
	{
		margin-top: 0;
		text-align: right;
		line-height: var(--f-carousel-dots-height);
	}

}

:root
{
	--f-spinner-width: 36px;
	--f-spinner-height: 36px;
	--f-spinner-color-1: rgba(0, 0, 0, 0.1);
	--f-spinner-color-2: rgba(17, 24, 28, 0.8);
	--f-spinner-stroke: 2.75
}

.f-spinner
{
	margin: auto;
	padding: 0;
	width: var(--f-spinner-width);
	height: var(--f-spinner-height)
}

.f-spinner svg
{
	width: 100%;
	height: 100%;
	vertical-align: top;
	animation: f-spinner-rotate 2s linear infinite
}

.f-spinner svg *
{
	stroke-width: var(--f-spinner-stroke);
	fill: none
}

.f-spinner svg *:first-child
{
	stroke: var(--f-spinner-color-1)
}

.f-spinner svg *:last-child
{
	stroke: var(--f-spinner-color-2);
	animation: f-spinner-dash 2s ease-in-out infinite
}

@keyframes f-spinner-rotate
{
	100%
	{
		transform: rotate(360deg)
	}
}

@keyframes f-spinner-dash
{
	0%
	{
		stroke-dasharray: 1, 150;
		stroke-dashoffset: 0
	}
	50%
	{
		stroke-dasharray: 90, 150;
		stroke-dashoffset: -35
	}
	100%
	{
		stroke-dasharray: 90, 150;
		stroke-dashoffset: -124
	}
}

.f-throwOutUp
{
	animation: .175s ease-out both f-throwOutUp
}

.f-throwOutDown
{
	animation: .175s ease-out both f-throwOutDown
}

@keyframes f-throwOutUp
{
	to
	{
		transform: translate3d(0, -150px, 0);
		opacity: 0
	}
}

@keyframes f-throwOutDown
{
	to
	{
		transform: translate3d(0, 150px, 0);
		opacity: 0
	}
}

.f-zoomInUp
{
	animation: var(--f-transition-duration, 0.2s) ease-out .1s both f-zoomInUp
}

.f-zoomOutDown
{
	animation: var(--f-transition-duration, 0.2s) ease-out both f-zoomOutDown
}

@keyframes f-zoomInUp
{
	from
	{
		transform: scale(0.975) translate3d(0, 16px, 0);
		opacity: 0
	}
	to
	{
		transform: scale(1) translate3d(0, 0, 0);
		opacity: 1
	}
}

@keyframes f-zoomOutDown
{
	to
	{
		transform: scale(0.975) translate3d(0, 16px, 0);
		opacity: 0
	}
}

.f-fadeIn
{
	animation: var(--f-transition-duration, 0.2s) ease both f-fadeIn;
	z-index: 2
}

.f-fadeOut
{
	animation: var(--f-transition-duration, 0.2s) ease both f-fadeOut;
	z-index: 1
}

@keyframes f-fadeIn
{
	0%
	{
		opacity: 0
	}
	100%
	{
		opacity: 1
	}
}

@keyframes f-fadeOut
{
	100%
	{
		opacity: 0
	}
}

.f-fadeSlowIn
{
	animation: var(--f-transition-duration, 0.5s) ease both f-fadeSlowIn;
	z-index: 2
}

.f-fadeSlowOut
{
	animation: var(--f-transition-duration, 0.5s) ease both f-fadeSlowOut;
	z-index: 1
}

@keyframes f-fadeSlowIn
{
	0%
	{
		opacity: 0
	}
	100%
	{
		opacity: 1
	}
}

@keyframes f-fadeSlowOut
{
	100%
	{
		opacity: 0
	}
}

.f-fadeFastIn
{
	animation: var(--f-transition-duration, 0.2s) ease-out both f-fadeFastIn;
	z-index: 2
}

.f-fadeFastOut
{
	animation: var(--f-transition-duration, 0.2s) ease-out both f-fadeFastOut;
	z-index: 2
}

@keyframes f-fadeFastIn
{
	0%
	{
		opacity: .75
	}
	100%
	{
		opacity: 1
	}
}

@keyframes f-fadeFastOut
{
	100%
	{
		opacity: 0
	}
}

.f-crossfadeIn
{
	animation: var(--f-transition-duration, 0.2s) ease-out both f-crossfadeIn;
	z-index: 2
}

.f-crossfadeOut
{
	animation: calc(var(--f-transition-duration, 0.2s) * .5) linear .1s both f-crossfadeOut;
	z-index: 1
}

@keyframes f-crossfadeIn
{
	0%
	{
		opacity: 0
	}
	100%
	{
		opacity: 1
	}
}

@keyframes f-crossfadeOut
{
	100%
	{
		opacity: 0
	}
}

.f-slideIn.from-next
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-slideInNext
}

.f-slideIn.from-prev
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-slideInPrev
}

.f-slideOut.to-next
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-slideOutNext
}

.f-slideOut.to-prev
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-slideOutPrev
}

@keyframes f-slideInPrev
{
	0%
	{
		transform: translateX(100%)
	}
	100%
	{
		transform: translate3d(0, 0, 0)
	}
}

@keyframes f-slideInNext
{
	0%
	{
		transform: translateX(-100%)
	}
	100%
	{
		transform: translate3d(0, 0, 0)
	}
}

@keyframes f-slideOutNext
{
	100%
	{
		transform: translateX(-100%)
	}
}

@keyframes f-slideOutPrev
{
	100%
	{
		transform: translateX(100%)
	}
}

.f-classicIn.from-next
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-classicInNext;
	z-index: 2
}

.f-classicIn.from-prev
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-classicInPrev;
	z-index: 2
}

.f-classicOut.to-next
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-classicOutNext;
	z-index: 1
}

.f-classicOut.to-prev
{
	animation: var(--f-transition-duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) f-classicOutPrev;
	z-index: 1
}

@keyframes f-classicInNext
{
	0%
	{
		transform: translateX(-75px);
		opacity: 0
	}
	100%
	{
		transform: translate3d(0, 0, 0);
		opacity: 1
	}
}

@keyframes f-classicInPrev
{
	0%
	{
		transform: translateX(75px);
		opacity: 0
	}
	100%
	{
		transform: translate3d(0, 0, 0);
		opacity: 1
	}
}

@keyframes f-classicOutNext
{
	100%
	{
		transform: translateX(-75px);
		opacity: 0
	}
}

@keyframes f-classicOutPrev
{
	100%
	{
		transform: translateX(75px);
		opacity: 0
	}
}

.f-carousel
{
	--f-carousel-theme-color: #706f6c;
	--f-carousel-spacing: 0px;
	--f-carousel-slide-width: 100%;
	--f-carousel-slide-height: auto;
	--f-carousel-slide-padding: 0;
	--f-button-width: 42px;
	--f-button-height: 42px;
	--f-button-color: var(--f-carousel-theme-color, currentColor);
	--f-button-hover-color: var(--f-carousel-theme-color, currentColor);
	--f-button-bg: transparent;
	--f-button-hover-bg: var(--f-button-bg);
	--f-button-active-bg: var(--f-button-bg);
	--f-button-svg-width: 24px;
	--f-button-svg-height: 24px;
	--f-button-next-pos: 10px;
	--f-button-prev-pos: 10px;
	position: relative;
	box-sizing: border-box
}

.f-carousel *, .f-carousel *:before, .f-carousel *:after
{
	box-sizing: inherit
}

.f-carousel.is-ltr
{
	direction: ltr
}

.f-carousel.is-rtl
{
	direction: rtl
}

.f-carousel__viewport
{
	overflow: hidden;
	transform: translate3d(0, 0, 0);
	backface-visibility: hidden;
	width: 100%;
	height: 100%
}

.f-carousel__viewport.is-draggable
{
	cursor: move;
	cursor: grab
}

.f-carousel__viewport.is-dragging
{
	cursor: move;
	cursor: grabbing
}

.f-carousel__track
{
	display: flex;
	margin: 0 auto;
	padding: 0;
	height: 100%;
	-webkit-tap-highlight-color: rgba(0, 0, 0, 0)
}

.f-carousel__slide
{
	position: relative;
	flex: 0 0 auto;
	width: var(--f-carousel-slide-width);
	max-width: 100%;
	height: var(--f-carousel-slide-height);
	margin: 0 var(--f-carousel-spacing) 0 0;
	padding: var(--f-carousel-slide-padding);
	overflow-x: hidden;
	overflow-y: auto;
	overscroll-behavior: contain;
	outline: 0;
	transform-origin: center center
}

.f-carousel__slide.is-loading
{
	min-height: 88px;
	min-width: 88px
}

.f-carousel.is-vertical
{
	--f-carousel-slide-height: 100%
}

.f-carousel.is-vertical .f-carousel__track
{
	flex-wrap: wrap
}

.f-carousel.is-vertical .f-carousel__slide
{
	margin: 0 0 var(--f-carousel-spacing) 0
}

:root
{
	--f-carousel-dots-width: 24px;
	--f-carousel-dots-height: 30px;
	--f-carousel-dot-width: 8px;
	--f-carousel-dot-height: 8px;
	--f-carousel-dot-radius: 50%;
	--f-carousel-dot-color: var(--f-carousel-theme-color, currentColor);
	--f-carousel-dot-opacity: 0.2;
	--f-carousel-dot-hover-opacity: 0.4
}

.f-carousel__dots
{
	position: absolute;
	bottom: calc(var(--f-carousel-dots-height) * -1);
	left: 0;
	right: 0;
	display: flex;
	justify-content: center;
	align-items: center;
	flex-wrap: wrap;
	margin: 0 auto !important;
	padding: 0;
	list-style: none !important;
	user-select: none
}

.f-carousel__dots li
{
	margin: 0;
	padding: 0;
	border: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	opacity: var(--f-carousel-dot-opacity);
	transition: opacity .15s ease-in-out
}

.f-carousel__dots li + li
{
	margin: 0
}

.f-carousel__dots li:hover
{
	opacity: var(--f-carousel-dot-hover-opacity)
}

.f-carousel__dots li.is-current
{
	opacity: 1
}

.f-carousel__dots li button
{
	appearance: none;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 0;
	padding: 0;
	width: var(--f-carousel-dots-width);
	height: var(--f-carousel-dots-height);
	border: 0;
	background: rgba(0, 0, 0, 0);
	cursor: pointer;
	transition: all .2s linear
}

.f-carousel__dot
{
	display: block;
	margin: 0;
	padding: 0;
	border: 0;
	width: var(--f-carousel-dot-width);
	height: var(--f-carousel-dot-height);
	border-radius: var(--f-carousel-dot-radius);
	background-color: var(--f-carousel-dot-color);
	line-height: 0;
	font-size: 0;
	cursor: pointer;
	pointer-events: none
}

.f-carousel__dots.is-dynamic li:not(.is-prev,.is-next,.is-current,.is-after-next,.is-before-prev) button
{
	transform: scale(0);
	width: 0
}

.f-carousel__dots.is-dynamic li.is-before-prev button, .f-carousel__dots.is-dynamic li.is-after-next button
{
	transform: scale(0.22)
}

.f-carousel__dots.is-dynamic li.is-prev button, .f-carousel__dots.is-dynamic li.is-next button
{
	transform: scale(0.66)
}

.f-carousel__dots.is-dynamic li.is-current button
{
	transform: scale(1)
}

.f-carousel__dots.is-dynamic li.is-before-prev button, .f-carousel__dots.is-dynamic li.is-after-next button
{
	transform: scale(0.33)
}

.f-carousel__dots.is-dynamic li.is-current:first-child
{
	margin-left: calc(var(--f-carousel-dots-width) * 2)
}

.f-carousel__dots.is-dynamic li.is-prev:first-child
{
	margin-left: var(--f-carousel-dots-width)
}

.f-carousel__dots.is-dynamic li.is-next:last-child
{
	margin-right: var(--f-carousel-dots-width)
}

.f-carousel__dots.is-dynamic li.is-current:last-child
{
	margin-right: calc(var(--f-carousel-dots-width) * 2)
}

.f-carousel.is-rtl .f-carousel__dots.is-dynamic .is-current:first-child
{
	margin-left: 0;
	margin-right: var(--f-carousel-dots-width)
}

.f-carousel.is-rtl .f-carousel__dots.is-dynamic .is-prev:first-child
{
	margin-left: 0;
	margin-right: var(--f-carousel-dots-width)
}

.f-carousel.is-rtl .f-carousel__dots.is-dynamic .is-current:last-child
{
	margin-left: 0;
	margin-right: var(--f-carousel-dots-width)
}

.f-carousel.is-rtl .f-carousel__dots.is-dynamic .is-next:last-child
{
	margin-right: 0;
	margin-left: var(--f-carousel-dots-width)
}

:root
{
	--f-button-width: 40px;
	--f-button-height: 40px;
	--f-button-border: 0;
	--f-button-border-radius: 0;
	--f-button-color: #374151;
	--f-button-bg: #f8f8f8;
	--f-button-hover-bg: #e0e0e0;
	--f-button-active-bg: #d0d0d0;
	--f-button-shadow: none;
	--f-button-transition: all 0.15s ease;
	--f-button-transform: none;
	--f-button-svg-width: 20px;
	--f-button-svg-height: 20px;
	--f-button-svg-stroke-width: 1.5;
	--f-button-svg-fill: none;
	--f-button-svg-filter: none;
	--f-button-svg-disabled-opacity: 0.65
}

.f-button
{
	display: flex;
	justify-content: center;
	align-items: center;
	box-sizing: content-box;
	position: relative;
	margin: 0;
	padding: 0;
	width: var(--f-button-width);
	height: var(--f-button-height);
	border: var(--f-button-border);
	border-radius: var(--f-button-border-radius);
	color: var(--f-button-color);
	background: var(--f-button-bg);
	box-shadow: var(--f-button-shadow);
	pointer-events: all;
	cursor: pointer;
	transition: var(--f-button-transition)
}

@media (hover: hover)
{
	.f-button:hover:not([disabled])
	{
		color: var(--f-button-hover-color);
		background-color: var(--f-button-hover-bg)
	}
}

.f-button:active:not([disabled])
{
	background-color: var(--f-button-active-bg)
}

.f-button:focus:not(:focus-visible)
{
	outline: none
}

.f-button:focus-visible
{
	outline: none;
	box-shadow: inset 0 0 0 var(--f-button-outline, 2px) var(--f-button-outline-color, var(--f-button-color))
}

.f-button svg
{
	width: var(--f-button-svg-width);
	height: var(--f-button-svg-height);
	fill: var(--f-button-svg-fill);
	stroke: currentColor;
	stroke-width: var(--f-button-svg-stroke-width);
	stroke-linecap: round;
	stroke-linejoin: round;
	transition: opacity .15s ease;
	transform: var(--f-button-transform);
	filter: var(--f-button-svg-filter);
	pointer-events: none
}

.f-button[disabled]
{
	cursor: default
}

.f-button[disabled] svg
{
	opacity: var(--f-button-svg-disabled-opacity)
}

.f-carousel__nav .f-button.is-prev, .f-carousel__nav .f-button.is-next, .fancybox__nav .f-button.is-prev, .fancybox__nav .f-button.is-next
{
	position: absolute;
	z-index: 1
}

.is-horizontal .f-carousel__nav .f-button.is-prev, .is-horizontal .f-carousel__nav .f-button.is-next, .is-horizontal .fancybox__nav .f-button.is-prev, .is-horizontal .fancybox__nav .f-button.is-next
{
	top: 50%;
	transform: translateY(-50%)
}

.is-horizontal .f-carousel__nav .f-button.is-prev, .is-horizontal .fancybox__nav .f-button.is-prev
{
	left: var(--f-button-prev-pos)
}

.is-horizontal .f-carousel__nav .f-button.is-next, .is-horizontal .fancybox__nav .f-button.is-next
{
	right: var(--f-button-next-pos)
}

.is-horizontal.is-rtl .f-carousel__nav .f-button.is-prev, .is-horizontal.is-rtl .fancybox__nav .f-button.is-prev
{
	left: auto;
	right: var(--f-button-next-pos)
}

.is-horizontal.is-rtl .f-carousel__nav .f-button.is-next, .is-horizontal.is-rtl .fancybox__nav .f-button.is-next
{
	right: auto;
	left: var(--f-button-prev-pos)
}

.is-vertical .f-carousel__nav .f-button.is-prev, .is-vertical .f-carousel__nav .f-button.is-next, .is-vertical .fancybox__nav .f-button.is-prev, .is-vertical .fancybox__nav .f-button.is-next
{
	top: auto;
	left: 50%;
	transform: translateX(-50%)
}

.is-vertical .f-carousel__nav .f-button.is-prev, .is-vertical .fancybox__nav .f-button.is-prev
{
	top: var(--f-button-next-pos)
}

.is-vertical .f-carousel__nav .f-button.is-next, .is-vertical .fancybox__nav .f-button.is-next
{
	bottom: var(--f-button-next-pos)
}

.is-vertical .f-carousel__nav .f-button.is-prev svg, .is-vertical .f-carousel__nav .f-button.is-next svg, .is-vertical .fancybox__nav .f-button.is-prev svg, .is-vertical .fancybox__nav .f-button.is-next svg
{
	transform: rotate(90deg)
}

// ########################## GLOBAL BASE SETUP #######################

html
{
	font: @xf-fontSizeNormal / @xf-lineHeightDefault sans-serif;
	font-family: @xf-fontFamilyUi;
	font-weight: @xf-fontWeightNormal;
	color: @xf-textColor;
	margin: 0;
	padding: 0;
	word-wrap: break-word;
	background-color: @xf-pageBg;

	/* // just a reminder that we *might* want this at some point
	-ms-text-size-adjust: none;
	-webkit-text-size-adjust: none;*/

	--js-display: block;
}

button, input, optgroup, select, textarea
{
	font-family: @xf-fontFamilyUi;
	line-height: @xf-lineHeightDefault;
}

img
{
	max-width: 100%;
	height: auto;
}

b, strong
{
	font-weight: @xf-fontWeightHeavy;
}

a
{
	.xf-link();

	&:hover
	{
		.xf-linkHover();
	}
}

svg
{
	fill: currentColor;
}

