				}
			}
		}
		&.fa-moon{
			&::before{
				.m-faContent(@fa-var-moon);
				:root[data-variation="alternate"] & {
					.m-faContent(@fa-var-solid-moon);
				}
			}
		}
	}
}
.js-styleVariationsLink.p-navgroup-link ,
.menu-content.js-styleVariationsMenu{	
